#!/usr/bin/env node
/**
 * 从 channels.mjs 生成 InvokeChannel 联合类型（阶段 3.5）。
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { INVOKE_CHANNELS } from '../electron/ipc/channels.mjs'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const outPath = path.join(root, 'src/shared/ipc-invoke-channels.ts')

const lines = [
  '// AUTO-GENERATED by scripts/gen-ipc-types.mjs — 勿手改。',
  '',
  '/** 主进程 ipcHandle 与 preload invoke 通道（与 electron/ipc/channels.mjs 一致）。 */',
  'export type InvokeChannel =',
  ...INVOKE_CHANNELS.map((ch, i) => `  | '${ch}'${i === INVOKE_CHANNELS.length - 1 ? '' : ''}`),
  '',
  'export const INVOKE_CHANNELS: readonly InvokeChannel[] = [',
  ...INVOKE_CHANNELS.map((ch) => `  '${ch}',`),
  '] as const',
  '',
]

const next = lines.join('\n')
const previous = fs.existsSync(outPath) ? fs.readFileSync(outPath, 'utf8') : ''
if (next !== previous) {
  fs.writeFileSync(outPath, next)
  console.log('gen-ipc-types: wrote src/shared/ipc-invoke-channels.ts')
} else {
  console.log('gen-ipc-types: already up to date')
}
